        controller.add(PageBackgroundHandler(onChange), contentWorld: pageBackgroundWorld,
                       name: PageScriptSources.pageBackgroundHandler)
    }

    /// The app's own world for `PageScriptSources.blockedMarker` (F6 §4.5):
