// Copyright (c) Tailscale Inc & contributors
// SPDX-License-Identifier: BSD-3-Clause

//  Created by Jonathan Nobels on 2025-12-16.
//

import SwiftUI
import WebKit

struct BrowserView: View {
    @ObservedObject var model: BrowserViewModel
    /// D3: the chosen gateway is not in the tailnet. The banner above owns the
    /// affordances; this only changes what the empty body says.
    var gatewayMissing: Bool = false
    /// Stops the load and opens the picker. One presentation path, owned by
    /// `DashboardContent` (M5 review), so Find, Change, the connecting hint and
    /// the error page cannot produce two overlapping sheets.
    var onChooseGateway: () -> Void = {}

    init(model: BrowserViewModel, gatewayMissing: Bool = false,
         onChooseGateway: @escaping () -> Void = {}) {
        self.model = model
        self.gatewayMissing = gatewayMissing
        self.onChooseGateway = onChooseGateway
    }

    var body: some View {
        // A ZStack, not a Group with an `if`: the web view stays in the
        // hierarchy in EVERY state (F4 §4.6). The old `if navError` branch
        // removed it, which tears down the very load being described and costs
        // a makeUIView on every retry.
        ZStack {
            // The web view is laid out INSIDE the top safe area, as it already
            // is at the bottom (F9 §0). It used to ignore it and extend under
            // the notch/Dynamic Island, which handed a viewport-fit=cover page
            // a 62pt inset it was trusted to honour — and a page that is not
            // an installed web app has every reason not to (KiroCrew 0.7.0
            // honours it only under display-mode: standalone). Now nothing is
            // above the page, it is told 0, and its y=0 is below the island
            // whatever CSS the gateway ships. Do not add
            // `.ignoresSafeArea(.container, edges: .top)` back; L1's
            // testInsetProbesReportWhatThePageIsTold fails if you do. Since
            // F15 the app bar sits between the safe-area top and this view.
            RawWebView(model: model)
                // A WKWebView belongs to exactly one tab; prevent
                // UIViewRepresentable from reusing the previous tab's view.
                .id(ObjectIdentifier(model))
                // Out of the accessibility tree while a state page covers it.
                // SwiftUI orders siblings by position, and the web view now
                // starts 62pt below the full-screen state page, so it sorts
                // AFTER it and wins the accessibility hit test: VoiceOver (and
                // XCUITest's isHittable) reached the web view through the error
                // page's buttons. Drawing order was never the problem.
                .accessibilityHidden(!model.pageState.leavesWebViewUncovered)
            PageStateView(state: model.pageState,
                          gatewayMissing: gatewayMissing,
                          onRetry: { model.reload() },
                          onChooseGateway: onChooseGateway)
        }
        // The strip between the island and the page, and the app bar in it,
        // take the page's canvas colour from `AppBarColumn` (F15), which owns
        // everything above the web view now. The window safe-area probe that
        // was overlaid on this view's corner lives in `DashboardContent`'s
        // background: it reads the window, so it never needed to sit on the page.
    }
}

/// The full-page error document shown in place of web content when navigation
/// fails. The `nav-error-overlay` identifier is retained for UI-test
/// compatibility even though this is no longer an overlay or modal card.
///
/// The URL is rendered **escaped** (via `debugEscaped`) so invisible or
/// problematic characters the keyboard may have injected — non-breaking space
/// (U+00A0), zero-width space (U+200B), smart quotes (U+201C/201D), tabs,
/// newlines, etc. — are visible as `\u{XXXX}` instead of silently breaking the
/// URL. `kind` distinguishes a URL **format** error (parse/validation rejected)
/// from a **retrieval** error (couldn't connect) via a small category label
/// (`NavErrorKind.caption`, host-tested): a SOCKS failure, which WebKit
/// reports as -1000 "bad URL", reads "Connection error", never "URL format
/// error" (F4 §4.3; the page itself is rebuilt by F4 §3.2).
    /// page nor a widget frame inside it can post to it.
    static let blockedMarkerWorld = WKContentWorld.world(name: "latchkey-blocked")

    /// What the marker script reports (F6 §4a).
    enum BlockedMarkerMessage {
        /// A trusted tap on a marked image: the image's URL.
        case open(URL)
        /// Increments since the last report.
        case counts(blocked: Int, gatewayFailed: Int)
        /// Off-origin resources the page loaded, by origin, as increments.
        case hosts([String: Int])
    }

    /// Installs the blocked-image marker. Every frame, not main-frame only:
    /// agent images render inside same-origin widget frames, which is exactly
    /// where a marker is needed. `onMessage` gets each well-formed message
    /// with the frame that sent it; the caller checks the frame's origin.
    static func installBlockedMarker(into controller: WKUserContentController,
                                     onMessage: @escaping (BlockedMarkerMessage, WKFrameInfo) -> Void) {
        controller.addUserScript(WKUserScript(source: PageScriptSources.blockedMarker,
                                              injectionTime: .atDocumentStart,
                                              forMainFrameOnly: false,
                                              in: blockedMarkerWorld))
        controller.add(BlockedMarkerHandler(onMessage), contentWorld: blockedMarkerWorld,
                       name: PageScriptSources.blockedMarkerHandler)
    }

    /// The app's own world for `PageScriptSources.appBarObserver`.
    static let appBarWorld = WKContentWorld.world(name: "latchkey-app-bar")

    /// Installs the app bar's finger observer (F15 §4a). `onSample` gets each
    /// touch-down, move and lift, and each change of the page's scroll
    /// range, main frame only. Called once per web view,
    /// before its first navigation.
    static func installAppBarObserver(into controller: WKUserContentController,
                                      onSample: @escaping (AppBarRetraction.Sample) -> Void) {
        controller.addUserScript(WKUserScript(source: PageScriptSources.appBarObserver,
                                              injectionTime: .atDocumentStart,
                                              forMainFrameOnly: true,
                                              in: appBarWorld))
        controller.add(AppBarHandler(onSample), contentWorld: appBarWorld,
                       name: PageScriptSources.appBarHandler)
    }
}

/// Decodes the observer's posts. Anything malformed is dropped: the bar's
/// safe state is shown, and a sample that is not understood changes nothing.
private final class AppBarHandler: NSObject, WKScriptMessageHandler {
    let onSample: (AppBarRetraction.Sample) -> Void
    init(_ onSample: @escaping (AppBarRetraction.Sample) -> Void) { self.onSample = onSample }

// Copyright (c) 2026 Olof Johansson
// SPDX-License-Identifier: BSD-3-Clause

//
//  PageScriptSources.swift
//  Latchkey
//
//  JavaScript the app injects into the dashboard, as source text only.
//
//  Kept apart from the `WKUserScript` construction (PageScripts.swift) and
//  free of WebKit, so `scripts/test-page-scripts.sh` can compile this file on
//  the host, print a script, and run it under Node against a fake `location`
//  and `history`. The test exercises the exact text the app injects.
//

import Foundation

enum PageScriptSources {
    /// Removes `token` from the address at document start (revision R2).
    ///
    /// A sign-in link is `https://<gateway>/?token=…`. By the time any script
    /// on that page runs, the token has already done its job: KiroCrew's auth
    /// middleware serves the page and sets the session and refresh cookies on
    /// that same response (`dashboard/token_auth.py:2891-3037` in 0.6.0).
    /// Leaving it in the address keeps a credential that is re-redeemable for
    /// 300 s in the back-forward list and in anything that reads the URL.
    ///
    /// Why document start, before the page's own scripts:
    ///  - React Router snapshots the location when it initialises. Rewriting
    ///    the URL after that leaves the router believing the query still holds
    ///    the token, and its next `setSearchParams` would write it back.
    ///  - It turns every sign-in load into the ordinary cookie-authenticated
    ///    load the app makes on every cold start, which is the most exercised
    ///    path the dashboard has.
    ///
    /// Cost, accepted: KiroCrew 0.6.0 reads `?token=` for one optional
    /// feature — a token carrying a `prompt` claim prefills the chat
    /// (`App-*.js`, the effect that calls its `YA()` decoder). Sign-in links
    /// minted by `kirocrew token` or the phone-access QR carry no prompt, so
    /// nothing is lost for them.
211:    static let blockedMarkerHandler = "kiroBlocked"
353:    static let pageBackgroundHandler = "latchkeyPageBackground"
411:    static let appBarHandler = "latchkeyAppBar"

